import { MeshPhysicalNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { color } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, CapsuleGeometry, Mesh, PointLight, AmbientLight, PlaneGeometry } = ctx.THREE;

  // Root container mapping coordinates of the node
  const container = new Group();

  // Local state tracker for active timelines
  let idleTimeline = null;
  const activeTimelines = [];
  const primitivesCleanup = [];

  // 1. PALETTE DEFINITIONS (from Visual specification)
  const colors = {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  // 2. DESIGN STAGE / BACKDROP (Ensures non-void background rendering)
  const backdropGeo = new PlaneGeometry(8, 6);
  const backdropMat = new MeshPhysicalNodeMaterial({
    color: colors.surface,
    roughness: 0.9,
    metalness: 0.1,
    transmission: 0.0,
    depthWrite: false,
  });
  const backdropPlane = new Mesh(backdropGeo, backdropMat);
  backdropPlane.position.set(0, 0, -1.5);
  container.add(backdropPlane);

  // 3. BADGE CONTAINER (Interactive Group)
  const badgeGroup = new Group();
  container.add(badgeGroup);

  // Capsule dimensions mapping standard watch bezel
  const capsuleLength = 1.4;
  const capsuleRadius = 0.45;

  // Procedural capsule label backing
  const badgeGeo = new CapsuleGeometry(capsuleRadius, capsuleLength, 8, 24);
  badgeGeo.rotateZ(Math.PI / 2); // Orient capsule horizontally

  // Premium machined-metal material with clearcoat
  const badgeMat = new MeshPhysicalNodeMaterial({
    color: colors.ink,
    roughness: 0.25,
    metalness: 0.85,
    clearcoat: 0.3,
    clearcoatRoughness: 0.1,
    reflectivity: 0.8,
  });

  const badgeMesh = new Mesh(badgeGeo, badgeMat);
  badgeMesh.castShadow = true;
  badgeMesh.receiveShadow = true;
  badgeGroup.add(badgeMesh);

  // Accent Edge Light Ring (Thin border glow outline)
  const borderGeo = new CapsuleGeometry(capsuleRadius + 0.012, capsuleLength + 0.005, 8, 24);
  borderGeo.rotateZ(Math.PI / 2);
  const borderMat = new MeshBasicNodeMaterial({
    color: colors.accent,
    transparent: true,
    opacity: 0.85,
  });
  const borderMesh = new Mesh(borderGeo, borderMat);
  borderMesh.position.z = -0.01;
  badgeGroup.add(borderMesh);

  // 4. EMBEDDED TEXT (JetBrains Mono equivalent)
  // Ensure we place a high contrast readable badge label
  const textLabel = ctx.fontAtlas.createText('JOURNAL', {
    fontSize: 0.14,
    color: colors.paper,
    align: 'left',
    letterSpacingPx: 0.05,
  });
  textLabel.position.set(-0.2, -0.05, 0.1);
  badgeGroup.add(textLabel);

  // 5. LOCALIZED LIGHTS (Enhances PBR and shadows on micro-details)
  const localDirectKey = new PointLight(colors.paper, 1.4, 6);
  localDirectKey.position.set(-1.5, 2, 2.5);
  badgeGroup.add(localDirectKey);

  const localAccentRim = new PointLight(colors.accent, 1.5, 4);
  localAccentRim.position.set(1.5, -1, 1);
  badgeGroup.add(localAccentRim);

  const localAmbient = new AmbientLight(colors.ink, 0.4);
  badgeGroup.add(localAmbient);

  // 6. ASSET LOADING (Machined-metal Gear-A)
  let gearMesh = null;
  if (config.meshUrl) {
    ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
      gearMesh = gltf.scene;

      // Unify scale and rotate to fit elegantly inside the capsule badge
      gearMesh.scale.setScalar(0.28);
      gearMesh.position.set(-0.6, 0.0, 0.12);
      gearMesh.rotation.x = Math.PI / 2;

      // Inject ultra-polished watchmaker metal shaders
      gearMesh.traverse((child) => {
        if (child.isMesh) {
          child.material = new MeshPhysicalNodeMaterial({
            color: colors.paper,
            roughness: 0.12,
            metalness: 0.95,
            clearcoat: 0.8,
            clearcoatRoughness: 0.05,
          });
        }
      });

      badgeGroup.add(gearMesh);

      // Create ticking / rotation animation to resemble active precision atelier engineering
      const anim = gsap.to(gearMesh.rotation, {
        y: Math.PI * 2,
        duration: 12,
        repeat: -1,
        ease: 'none',
      });
      activeTimelines.push(anim);
    }).catch(err => {
      console.warn("PrismNode failed to load design asset gear-a:", err);
    });
  }

  // 7. CINEMATIC PRIMITIVES APPLICATION
  if (config.cinematicPrimitives) {
    config.cinematicPrimitives.forEach((primitive) => {
      if (ctx.primitives[primitive.name]) {
        try {
          const res = ctx.primitives[primitive.name](badgeGroup, primitive.params);
          if (res) {
            if (res.timeline) activeTimelines.push(res.timeline);
            if (res.cleanup) primitivesCleanup.push(res.cleanup);
          }
        } catch (e) {
          console.warn(`Failed mapping primitive ${primitive.name}`, e);
        }
      }
    });
  }

  // Fallback default cinematic primitives if list was empty
  if (!config.cinematicPrimitives || config.cinematicPrimitives.length === 0) {
    if (ctx.primitives['parallax-scroll']) {
      const res = ctx.primitives['parallax-scroll'](badgeGroup, { intensity: 0.4 });
      if (res) {
        if (res.timeline) activeTimelines.push(res.timeline);
        if (res.cleanup) primitivesCleanup.push(res.cleanup);
      }
    }
    if (ctx.primitives['magnetic-cursor']) {
      const res = ctx.primitives['magnetic-cursor'](badgeGroup, { radius: 1.2, strength: 0.35 });
      if (res) {
        if (res.timeline) activeTimelines.push(res.timeline);
        if (res.cleanup) primitivesCleanup.push(res.cleanup);
      }
    }
  }

  // 8. INTERACTION HANDLERS (Hover-rise, Click-emit)
  let isHovered = false;

  container.userData = {
    handlers: {
      pointerover: () => {
        if (isHovered) return;
        isHovered = true;

        // Visual feedback - Weighted settle rise-in (subtle, 0.15 scene units)
        gsap.to(badgeGroup.position, {
          y: 0.15,
          z: 0.12,
          duration: 0.5,
          ease: 'power3.out',
          overwrite: 'auto',
        });

        gsap.to(badgeMesh.material, {
          color: '#2a2a35',
          duration: 0.3,
          overwrite: 'auto',
        });
      },
      pointerout: () => {
        isHovered = false;

        gsap.to(badgeGroup.position, {
          y: 0,
          z: 0,
          duration: 0.5,
          ease: 'power4.out',
          overwrite: 'auto',
        });

        gsap.to(badgeMesh.material, {
          color: colors.ink,
          duration: 0.4,
          overwrite: 'auto',
        });
      },
      click: () => {
        // Micro-interaction on trigger
        gsap.to(badgeGroup.scale, {
          x: 0.94,
          y: 0.94,
          z: 0.94,
          duration: 0.1,
          yoyo: true,
          repeat: 1,
          ease: 'power2.out',
        });

        // Event emission routing
        ctx.emit('hub-journal.select', { id: 'journal-badge' });
      },
    },
    // Resource Management & Thread Protection
    cleanup: () => {
      activeTimelines.forEach((tl) => {
        if (tl && typeof tl.kill === 'function') tl.kill();
      });
      if (idleTimeline) idleTimeline.kill();
      primitivesCleanup.forEach((fn) => {
        if (typeof fn === 'function') fn();
      });
      // Dispose materials & geometries
      badgeGeo.dispose();
      badgeMat.dispose();
      borderGeo.dispose();
      borderMat.dispose();
      backdropGeo.dispose();
      backdropMat.dispose();
    },
  };

  return container;
}
